import React, { useContext, useState } from "react";
import "./Navbar.css";
import logo from "../Assets/logo.png";
import cart_icon from "../Assets/cart_icon.png";
import menu_icon from "../Assets/menu.png"; // Add a hamburger menu icon
import close_icon from "../Assets/close.png"; // Add a close icon
import { Link } from "react-router-dom";
import { ShopContext } from "../../context/ShopContext";

const Navbar = () => {
  const [menu, setMenu] = useState("shop");
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false); // For responsive menu toggle
  const { getTotalCartItems } = useContext(ShopContext);

  const toggleMobileMenu = () => {
    setMobileMenuOpen((prev) => !prev);
  };

  return (
    <div className="navbar">
      <div className="nav-logo">
        <img src={logo} alt="logo" />
        <p>Shopper</p>
      </div>

      <div className={`nav-menu ${mobileMenuOpen ? "active" : ""}`}>
        <li onClick={() => { setMenu("shop"); setMobileMenuOpen(false); }}>
          <Link to="/" style={{ textDecoration: "none" }}>Shop</Link>
          {menu === "shop" && <hr />}
        </li>
        <li onClick={() => { setMenu("mens"); setMobileMenuOpen(false); }}>
          <Link to="/mens" style={{ textDecoration: "none" }}>Men</Link>
          {menu === "mens" && <hr />}
        </li>
        <li onClick={() => { setMenu("womens"); setMobileMenuOpen(false); }}>
          <Link to="/womens" style={{ textDecoration: "none" }}>Women</Link>
          {menu === "womens" && <hr />}
        </li>
        <li onClick={() => { setMenu("kids"); setMobileMenuOpen(false); }}>
          <Link to="/kids" style={{ textDecoration: "none" }}>Kids</Link>
          {menu === "kids" && <hr />}
        </li>
      </div>

      <div className="nav-login-cart">
        <Link to="/login">
          <button>Login</button>
        </Link>
        <Link to="/cart">
          <img src={cart_icon} alt="cart" />
        </Link>
        <div className="nav-cart-count">{getTotalCartItems()}</div>
        <img
          src={mobileMenuOpen ? close_icon : menu_icon}
          alt="menu toggle"
          className="nav-menu-icon"
          onClick={toggleMobileMenu}
        />
      </div>
    </div>
  );
};

export default Navbar;
